<script setup lang="ts">
import {computed,ref} from 'vue'
import {unlockGroups,applicableRegions} from '../unlock'
import type {ServiceRule} from '../domain'
const props=defineProps<{catalog:ServiceRule[];modelValue:Record<string,string[]>}>(),emit=defineEmits<{'update:modelValue':[Record<string,string[]>]}>()
const selected=ref('chatgpt_unlock'),search=ref(''),names=new Intl.DisplayNames(['zh-CN'],{type:'region'})
const codes='HK MO TW JP SG US KR GB DE FR NL AU CA CN RU TH MY VN PH ID IN TR AE AR BR IT ES SE CH PL ZA KH EG NG PK AT BE BG CY CZ DK EE FI GR HR HU IE IS LT LU LV MT NO NZ PT RO RS SA SK SI UA IL MX CL CO PE BD LK NP MM LA MN KZ UZ GE AM AZ QA KW BH OM JO LB MA TN DZ KE TZ UG GH ET MU SC MV FJ PG BS PA CR DO EC UY VE BO PY CU PR JM TT HN SV GT NI BZ HT GD LC VC AG BB KN DM SR GY GF RE YT NC PF GL FO GI GG JE IM VA SM MC LI AD ME MK AL BA MD BY BQ CW SX AW BM KY VG VI TC AI MS GP MQ BL MF AX AF IR IQ SY YE PS BT BN TL IO CC CX NF CK NU TK TO WS VU SB TV NR KI FM MH PW AS GU MP EH LY SD SS SO DJ ER RW BI CD CG GA GQ ST AO ZM ZW MZ MW BW NA LS SZ GM GN GW LR SL SN ML BF NE TD CF CM CV KM MG BJ TG CI MR'.split(' ')
const regions=computed(()=>[...new Set([...codes,...Object.values(props.modelValue).flat()])].map(code=>({code,name:names.of(code)||code})).filter(r=>(r.code+' '+r.name).toLowerCase().includes(search.value.toLowerCase())))
const services=computed(()=>unlockGroups.map(g=>({...g,items:props.catalog.filter(s=>(g.ids as string[]).includes(s.service_id))})))
const current=computed(()=>applicableRegions(selected.value,props.modelValue)),serviceName=computed(()=>props.catalog.find(s=>s.service_id===selected.value)?.name||selected.value)
function toggle(code:string,checked:boolean){emit('update:modelValue',{...props.modelValue,[selected.value]:checked?[...current.value,code]:current.value.filter(r=>r!==code)})}
</script>
<template><section class="settings-section region-editor"><h2>解锁服务适用地区</h2><p>空选表示所有地区。优先按真实落地判断，没有结果时按名称判断。修改后点击“保存设置”。</p><div class="region-columns"><nav aria-label="选择地区规则服务"><section v-for="g in services" :key="g.id"><h3>{{g.name}}</h3><button v-for="s in g.items" :key="s.service_id" type="button" :class="{selected:selected===s.service_id}" :aria-pressed="selected===s.service_id" @click="selected=s.service_id">{{s.name}}<small>{{applicableRegions(s.service_id,modelValue).join(' · ')||'所有地区'}}</small></button></section></nav><div class="region-options"><header><strong>{{serviceName}}</strong><button type="button" class="button ghost" @click="emit('update:modelValue',{...modelValue,[selected]:[]})">不限地区</button></header><input v-model="search" type="search" placeholder="搜索地区或代码" aria-label="搜索适用地区"><div class="region-checks"><label v-for="r in regions" :key="r.code"><input type="checkbox" :checked="current.includes(r.code)" @change="toggle(r.code,($event.target as HTMLInputElement).checked)">{{r.name}} <small>{{r.code}}</small></label></div></div></div></section></template>
<style scoped>
.region-editor p{font-size:12px;color:var(--cst-muted)}.region-columns{display:grid;grid-template-columns:210px minmax(0,1fr);gap:20px}.region-columns nav,.region-options{max-height:300px;overflow:auto}.region-columns h3{font-size:12px;color:var(--cst-muted);margin:10px 0 5px}.region-columns nav button{display:block;text-align:left;width:100%;border:0;background:transparent;border-radius:6px;padding:6px 9px;color:var(--ink);cursor:pointer}.region-columns nav button.selected{background:var(--blue-soft,#eaf2ff);color:var(--blue)}.region-columns nav small{display:block;font-size:10px;color:var(--cst-muted);margin-top:3px}.region-options header{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}.region-options>input{width:100%;margin-bottom:10px}.region-checks{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.region-checks label{display:flex;align-items:center;gap:5px;font-size:12px}.region-checks input[type=checkbox]{width:15px;height:15px;min-height:0;padding:0;margin:0;flex:none}.region-checks small{color:var(--cst-muted)}@media(max-width:700px){.region-columns{grid-template-columns:160px minmax(0,1fr)}.region-checks{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
